typedef struct { int hour; double temp; } Reading;

int hottest_hour(const Reading log[], int n)
{
    return log[0].hour;
}

exercises.solution:
typedef struct { int hour; double temp; } Reading;

int hottest_hour(const Reading log[], int n)
{
    int best = 0;
    for (int i = 1; i < n; i++)
        if (log[i].temp > log[best].temp) best = i;
    return log[best].hour;
}

