exercises.solution:
typedef struct { double level; double capacity; } Tank;

void tank_add(Tank *t, double litres)
{
    t->level += litres;
    if (t->level > t->capacity) t->level = t->capacity;
    if (t->level < 0) t->level = 0;
}
